"""
GTK 3 & GTK 4 (Thunar, Libadwaita) Theme Updater
"""

from config import GTK3_DIR, GTK4_DIR


def update_gtk(pal):
    colors_content = f"""/* Material 3 Dark Palette for GTK */
/* Auto-generated by change-wallpaper using materialyoucolor */

@define-color theme_bg_color {pal["surface"]};
@define-color theme_fg_color {pal["on_surface"]};
@define-color theme_base_color {pal["surface_container_lowest"]};
@define-color theme_text_color {pal["on_surface"]};
@define-color theme_selected_bg_color {pal["primary"]};
@define-color theme_selected_fg_color {pal["on_primary"]};
@define-color theme_unfocused_bg_color {pal["surface"]};
@define-color theme_unfocused_fg_color {pal["on_surface_variant"]};
@define-color theme_unfocused_base_color {pal["surface_container_lowest"]};
@define-color theme_unfocused_text_color {pal["on_surface_variant"]};
@define-color theme_unfocused_selected_bg_color {pal["surface_container_high"]};
@define-color theme_unfocused_selected_fg_color {pal["primary"]};
@define-color borders {pal["outline_variant"]};
@define-color unfocused_borders {pal["outline_variant"]};
@define-color warning_color {pal["yellow"]};
@define-color error_color {pal["error"]};
@define-color success_color {pal["green"]};

/* Breeze compatibility overrides */
@define-color content_view_bg_breeze {pal["surface"]};
@define-color theme_base_color_breeze {pal["surface_container_lowest"]};
@define-color theme_bg_color_breeze {pal["surface"]};
@define-color theme_fg_color_breeze {pal["on_surface"]};
@define-color theme_text_color_breeze {pal["on_surface"]};
@define-color theme_selected_bg_color_breeze {pal["primary"]};
@define-color theme_selected_fg_color_breeze {pal["on_primary"]};
@define-color theme_hovering_selected_bg_color_breeze {pal["primary_container"]};
@define-color theme_button_background_normal_breeze {pal["surface_container"]};
@define-color theme_button_background_backdrop_breeze {pal["surface_container"]};
@define-color theme_button_foreground_normal_breeze {pal["on_surface"]};
@define-color theme_header_background_breeze {pal["surface_container"]};
@define-color theme_header_foreground_breeze {pal["on_surface"]};
@define-color theme_titlebar_background_breeze {pal["surface_container"]};
@define-color theme_titlebar_foreground_breeze {pal["on_surface"]};
@define-color borders_breeze {pal["outline_variant"]};
@define-color link_color_breeze {pal["primary"]};

/* Libadwaita & GTK4 Standard Palette */
@define-color accent_color {pal["primary"]};
@define-color accent_bg_color {pal["primary"]};
@define-color accent_fg_color {pal["on_primary"]};
@define-color window_bg_color {pal["surface"]};
@define-color window_fg_color {pal["on_surface"]};
@define-color view_bg_color {pal["surface"]};
@define-color view_fg_color {pal["on_surface"]};
@define-color headerbar_bg_color {pal["surface_container"]};
@define-color headerbar_fg_color {pal["on_surface"]};
@define-color headerbar_border_color {pal["outline_variant"]};
@define-color headerbar_backdrop_color {pal["surface"]};
@define-color card_bg_color {pal["surface_container"]};
@define-color card_fg_color {pal["on_surface"]};
@define-color card_border_color {pal["outline_variant"]};
@define-color popover_bg_color {pal["surface_container"]};
@define-color popover_fg_color {pal["on_surface"]};
@define-color dialog_bg_color {pal["surface_container"]};
@define-color dialog_fg_color {pal["on_surface"]};
"""

    for gtk_dir in [GTK3_DIR, GTK4_DIR]:
        gtk_dir.mkdir(parents=True, exist_ok=True)
        (gtk_dir / "colors.css").write_text(colors_content)

    # GTK3 specific custom styling (Thunar)
    gtk3_content = f"""@import 'colors.css';

/* ==========================================================
   Material Design 3 Dark Theme for Thunar & GTK3
   Auto-generated by change-wallpaper using materialyoucolor
   ========================================================== */

/* Thunar main window */
window.thunar,
.thunar {{
  background-color: @theme_bg_color;
  color: @theme_fg_color;
}}

/* Thunar Sidebar / Side Pane */
.thunar .sidebar,
.thunar .shortcuts-pane,
.thunar .tree-pane {{
  background-color: {pal["surface_container"]};
  color: {pal["on_surface"]};
  border-right: 1px solid {pal["outline_variant"]};
}}

.thunar .sidebar .view {{
  background-color: transparent;
  color: {pal["on_surface"]};
}}

.thunar .sidebar .view:selected {{
  background-color: {pal["surface_container_high"]};
  color: {pal["primary"]};
  border-radius: 10px;
}}

/* Thunar Main Content View */
.thunar .standard-view .view,
.thunar .view {{
  background-color: {pal["surface"]};
  color: {pal["on_surface"]};
}}

.thunar .view:selected,
.thunar .view:selected:focus {{
  background-color: {pal["surface_container_high"]};
  color: {pal["primary"]};
  border: 1px solid {pal["primary"]};
  border-radius: 10px;
}}

/* Thunar Toolbar & Header */
.thunar toolbar,
.thunar .primary-toolbar {{
  background-color: {pal["surface"]};
  border-bottom: 1px solid {pal["outline_variant"]};
  padding: 4px;
}}

/* Location Bar / Path Bar (Material 3 Pill Shape) */
.thunar .location-bar entry,
.thunar .path-bar-box,
.thunar entry {{
  background-color: {pal["surface_container_lowest"]};
  color: {pal["on_surface"]};
  border: 1px solid {pal["outline_variant"]};
  border-radius: 16px;
  padding: 6px 12px;
}}

.thunar entry:focus {{
  border-color: {pal["primary"]};
  box-shadow: 0 0 0 1px {pal["primary"]};
}}

/* Thunar Path Bar Buttons (Pill Chips) */
.thunar .path-bar button {{
  background-color: {pal["surface_container"]};
  color: {pal["on_surface"]};
  border: 1px solid {pal["outline_variant"]};
  border-radius: 12px;
  margin: 2px;
  padding: 4px 10px;
}}

.thunar .path-bar button:checked {{
  background-color: {pal["surface_container_high"]};
  color: {pal["primary"]};
  border-color: {pal["primary"]};
  font-weight: bold;
}}

/* Thunar Statusbar */
.thunar statusbar {{
  background-color: {pal["surface_container"]};
  color: {pal["on_surface_variant"]};
  border-top: 1px solid {pal["outline_variant"]};
  padding: 2px 8px;
}}
"""
    (GTK3_DIR / "gtk.css").write_text(gtk3_content)

    # GTK4 styling cleanly imports colors without overriding popover/menu geometries
    gtk4_content = """@import 'colors.css';
"""
    (GTK4_DIR / "gtk.css").write_text(gtk4_content)
